import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------- CUDA kernel --------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv2d_fp16_kernel(const __half* __restrict__ input,
                                   const __half* __restrict__ weight,
                                   __half* __restrict__ output,
                                   int N, int C_in, int H_in, int W_in,
                                   int C_out, int K_h, int K_w,
                                   int stride_h, int stride_w,
                                   int pad_h, int pad_w,
                                   int H_out, int W_out) {
    int total = N * C_out * H_out * W_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < total; i += stride) {
        int w = i % W_out;
        int tmp = i / W_out;
        int h = tmp % H_out;
        tmp = tmp / H_out;
        int c_out = tmp % C_out;
        int n = tmp / C_out;

        float sum = 0.0f;
        for (int c = 0; c < C_in; ++c) {
            for (int kh = 0; kh < K_h; ++kh) {
                int in_h = h * stride_h - pad_h + kh;
                if (in_h < 0 || in_h >= H_in) continue;
                for (int kw = 0; kw < K_w; ++kw) {
                    int in_w = w * stride_w - pad_w + kw;
                    if (in_w < 0 || in_w >= W_in) continue;
                    int input_idx  = ((n * C_in + c) * H_in + in_h) * W_in + in_w;
                    int weight_idx = ((c_out * C_in + c) * K_h + kh) * K_w + kw;
                    sum += __half2float(input[input_idx]) *
                           __half2float(weight[weight_idx]);
                }
            }
        }
        output[i] = __float2half(sum);
    }
}

void conv2d_fp16(torch::Tensor input,
                 torch::Tensor weight,
                 torch::Tensor output,
                 int stride_h, int stride_w,
                 int pad_h, int pad_w) {
    const int N     = input.size(0);
    const int C_in  = input.size(1);
    const int H_in  = input.size(2);
    const int W_in  = input.size(3);
    const int C_out = weight.size(0);
    const int K_h   = weight.size(2);
    const int K_w   = weight.size(3);
    const int H_out = output.size(2);
    const int W_out = output.size(3);

    const int threads = 256;
    const int blocks  = (N * C_out * H_out * W_out + threads - 1) / threads;

    conv2d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        N, C_in, H_in, W_in,
        C_out, K_h, K_w,
        stride_h, stride_w,
        pad_h, pad_w,
        H_out, W_out);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in conv2d_fp16: %s\\n", cudaGetErrorString(err));
    }
}
'''

conv2d_mod = load_inline(name='conv2d_fp16_mod',
                         cpp_sources='',
                         cuda_sources=cuda_src,
                         functions=['conv2d_fp16'],
                         verbose=False)

