class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.out_channels = 96
        self.in_channels  = 3
        self.kernel_size  = 11
        self.stride       = 4
        self.padding      = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels,
                        self.in_channels,
                        self.kernel_size,
                        self.kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, x):
        # ensure fp16 and contiguous
        x = x.to(dtype=torch.float16, device='cuda').contiguous()
        N, _, H, W = x.shape
        H_out = (H + 2 * self.padding - self.kernel_size) // self.stride + 1
        W_out = (W + 2 * self.padding - self.kernel_size) // self.stride + 1

        out = torch.empty(N,
                          self.out_channels,
                          H_out,
                          W_out,
                          dtype=torch.float16,
                          device='cuda')

        conv2d_mod.conv2d_fp16(x,
                               self.weight,
                               out,
                               self.stride,
                               self.stride,
                               self.padding,
                               self.padding)
        return out
